use Civi\Lughauth\Features\OAuth\Authentication\Application\TokenGranter\ResolverForPassword;
use Civi\Lughauth\Features\OAuth\Authentication\Application\TokenGranter\ResolverForRefresh;
use Civi\Lughauth\Features\OAuth\Authentication\Application\TokenGranter\ResolverForDevice;
