    // --- helpers ---

    private function makeLoginUsecase(?AuthenticationResult $result = null): LoginUsecase
    {
        return new class ($result) extends LoginUsecase {
            public function __construct(private ?AuthenticationResult $r = null)
            {
            }
            public function validatedUserData(string $t, string $u, string $p, AuthenticationRequest $r): AuthenticationResult
            {
                return $this->r ?? new AuthenticationResult(valid: true, id: 'u1', tenant: $t);
            }
            public function fillPreLoadById(string $t, AuthenticationRequest $r, ChallengesState $c): AuthenticationResult
            {
                return $this->r ?? new AuthenticationResult(valid: true, id: 'u1');
            }
        };
    }

    private function makeRefreshResolver(
        TokenSigner $signer,
        ?TokenRevocationGateway $revocation = null,
        ?InMemorySessionStore $sessions = null,
        ?LoginUsecase $login = null
    ): ResolverForRefresh {
        $context = $this->createStub(Context::class);
        $context->method('getIssuer')->willReturnCallback(fn (string $tenant): string => 'https://issuer/' . $tenant);
        return new ResolverForRefresh(
            $login ?? $this->makeLoginUsecase(),
            $signer,
            $revocation ?? new InMemoryTokenRevocation(),
            $sessions ?? new InMemorySessionStore(),
            $context
        );
    }

    /** Public sid of the session opened by makeSessions, which is not its state key. */
    private function publicSid(InMemorySessionStore $sessions): string
    {
        return (string) $sessions->loadSession('state-1')?->publicSid;
    }

    private function makeSessions(string $state, string $userId, string $issuer): InMemorySessionStore
    {
        $sessions = new InMemorySessionStore();
        $sessions->saveSession(
            $state,
            new ClientData('c', ['authorization_code'], true),
            $issuer,
            new ChallengesState(),
            new AuthenticationResult(valid: true, id: $userId),
            'csid',
            new \DateInterval('P1D')
        );
        return $sessions;
    }

    private function makeSigner(?array $payload = null): TokenSigner
    {
        // Rotated refresh tokens always carry a jti and a family; tests may unset them with null.
        $payload = $payload === null ? null : array_filter(['jti' => 'jti-1', 'fid' => 'fam-1', ...$payload], fn ($v) => $v !== null);
        return new class ($payload) implements TokenSigner {
            public function __construct(private ?array $payload)
            {
            }
            public function sign(\Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\TokenType $type, array $d, string $t, \DateInterval $e): string
            {
                return 'tok';
            }
            public function keysAsJwks(string $t): \Jose\Component\Core\JWKSet
            {
                return new \Jose\Component\Core\JWKSet([]);
            }
            public function signKeypass(string $t, array $d, \DateInterval $e): string
            {
                return '';
            }
            public function verify(string $t, string $tok, \Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\VerificationPolicy $policy): ?array
            {
                return $this->payload;
            }
            public function verifiedKeypass(string $t, string $tok): mixed
            {
                return null;
            }
        };
    }

